import type { ChangeEvent, FormEvent, KeyboardEvent } from 'react'
import { useCallback, useEffect, useRef, useState } from 'react'
import type { CardDraft, CardTypeConfig, StateConfig } from '../../../data/data_types'
import { useCardCreationState } from '../../hooks/use_card_creation_state'
import type { MarkdownEditorHandle } from '../../editor/markdown_editor'
import { CardTypePillGroup } from './card_type_pill_group'
import { NewCardMarkdownEditor } from './new_card_markdown_editor'
import { projectSessionService } from '../../../services/project/project_session_service'
import { dialogService } from '../../../services/dialog_service'
import { NewCardColumnPicker } from './new_card_column_picker'

const DIALOG_WIDTH = 480
const DISCARD_CARD_MESSAGE = 'Discard this new card draft?'

interface NewCardDialogProps {
    cardBodyTemplate: string
    cardTypes: CardTypeConfig[]
    initialTargetStatus: string
    isLoading: boolean
    isProjectOpen: boolean
    open: boolean
    onClose: () => void
    onCreateCard: (draft: CardDraft, initialState: string) => Promise<void>
    states: StateConfig[]
}

/** Responsive form for creating a card in a selected board column. */
export function NewCardDialog(props: NewCardDialogProps) {
    const {
        cardBodyTemplate,
        cardTypes,
        initialTargetStatus,
        isLoading,
        isProjectOpen,
        onClose,
        onCreateCard,
        open,
        states,
    } = props
    const { isCreatingCard } = useCardCreationState()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const bodyEditorRef = useRef<MarkdownEditorHandle>(null)
    const wasOpenRef = useRef(false)
    const [isInsertedTemplateUntouched, setIsInsertedTemplateUntouched] = useState(false)
    const [targetStatus, setTargetStatus] = useState('')
    const [title, setTitle] = useState('')
    const [type, setType] = useState('')
    const defaultType = cardTypes[0]?.type ?? ''
    const defaultStatus = states[0]?.state ?? ''
    const selectedType = cardTypes.some((typeConfig) => typeConfig.type === type) ? type : defaultType
    const selectedStatus = states.some((stateConfig) => stateConfig.state === targetStatus) ? targetStatus : defaultStatus
    const isSubmitDisabled = !isProjectOpen || title.trim().length === 0
        || selectedType.length === 0 || selectedStatus.length === 0 || isLoading || isCreatingCard

    const resetForm = () => {
        bodyEditorRef.current?.setMarkdown('')
        setIsInsertedTemplateUntouched(false)
        setTargetStatus(initialTargetStatus)
        setTitle('')
        setType(defaultType)
    }

    useEffect(() => {
        if ((open && !wasOpenRef.current) || !isProjectOpen) {
            bodyEditorRef.current?.setMarkdown('')
            setIsInsertedTemplateUntouched(false)
            setTargetStatus(initialTargetStatus)
            setTitle('')
            setType(defaultType)
        }
        wasOpenRef.current = open && isProjectOpen
    }, [defaultType, initialTargetStatus, isProjectOpen, open])

    const closeDialog = async () => {
        const body = bodyEditorRef.current?.getMarkdown() ?? ''
        const isDirty = title.length > 0
            || body.length > 0
            || selectedType !== defaultType
            || selectedStatus !== initialTargetStatus
            || projectSessionService.hasNewCardDraftImages()
        if (isDirty && !window.confirm(DISCARD_CARD_MESSAGE)) return

        try {
            await projectSessionService.discardNewCardDraftImages()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Pasted draft images could not be removed' })
            return
        }
        resetForm()
        onClose()
    }

    const handleDialogClose = () => {
        void closeDialog()
    }

    const handleTitleChange = (event: ChangeEvent<HTMLInputElement>) => {
        setTitle(event.target.value)
    }

    const handleBodyDirtyChange = useCallback((dirty: boolean) => {
        if (dirty) setIsInsertedTemplateUntouched(false)
    }, [])

    const handleTemplateClick = () => {
        const body = bodyEditorRef.current?.getMarkdown() ?? ''
        if (isInsertedTemplateUntouched && body === cardBodyTemplate) {
            bodyEditorRef.current?.setMarkdown('')
            setIsInsertedTemplateUntouched(false)

            return
        }

        const nextBody = body.length > 0 ? `${body}\n\n${cardBodyTemplate}` : cardBodyTemplate
        bodyEditorRef.current?.setMarkdown(nextBody)
        setIsInsertedTemplateUntouched(body.length === 0)
    }

    const handleCreateClick = async () => {
        if (isSubmitDisabled) return

        await projectSessionService.waitForNewCardImageSaves()
        const body = bodyEditorRef.current?.getMarkdown() ?? ''
        const draft: CardDraft = {
            body,
            bodyIncludesTemplate: true,
            title: title.trim(),
            type: selectedType,
        }
        try {
            await onCreateCard(draft, selectedStatus)
        } catch {
            return
        }
        resetForm()
    }

    const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault()
        await handleCreateClick()
    }

    const handleFormKeyDown = (event: KeyboardEvent<HTMLFormElement>) => {
        if (event.key !== 'Escape') return

        event.preventDefault()
        void closeDialog()
    }

    const handleFormKeyDownCapture = (event: KeyboardEvent<HTMLFormElement>) => {
        if (event.key !== 'Enter' || !event.ctrlKey) return

        event.preventDefault()
        event.stopPropagation()
        void handleCreateClick()
    }

    const templateButtonLabel = isInsertedTemplateUntouched ? 'Clear' : 'Template'
    const createButton = (
        <Button aria-label="Create card" disabled={isSubmitDisabled} type="submit" variant="contained">
            <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                <Plus sx={{ fontSize: 17 }} />
                <span>Add</span>
                {!isMobile ? (
                    <Box
                        component="span"
                        sx={{
                            bgcolor: 'rgba(255,255,255,0.18)',
                            borderRadius: '5px',
                            fontSize: 10.5,
                            fontWeight: 600,
                            px: 0.625,
                            py: 0.25,
                        }}
                    >
                        Ctrl+â†µ
                    </Box>
                ) : null}
            </Stack>
        </Button>
    )

    return (
        <Dialog
            aria-labelledby="new-card-dialog-heading"
            fullScreen={isMobile}
            maxWidth={false}
            onClose={handleDialogClose}
            open={open}
            slotProps={{
                backdrop: { sx: { backdropFilter: 'blur(2px)', backgroundColor: 'rgba(16, 24, 40, 0.45)' } },
                paper: {
                    sx: {
                        border: isMobile ? 0 : 1,
                        borderColor: 'divider',
                        borderRadius: isMobile ? 0 : '14px',
                        boxShadow: isMobile ? 'none' : '0 24px 60px rgba(16,24,40,0.28)',
                        height: isMobile ? '100dvh' : 'auto',
                        maxHeight: isMobile ? '100dvh' : 'calc(100dvh - 32px)',
                        maxWidth: isMobile ? '100%' : 'calc(100% - 32px)',
                        overflow: 'hidden',
                        width: isMobile ? '100%' : DIALOG_WIDTH,
                    },
                },
            }}
        >
            <Box
                component="form"
                onKeyDown={handleFormKeyDown}
                onKeyDownCapture={handleFormKeyDownCapture}
                onSubmit={handleSubmit}
                sx={{ display: 'flex', flexDirection: 'column', height: isMobile ? '100%' : 'auto', maxHeight: '100dvh', minHeight: 0 }}
            >
                <DialogTitle
                    component="div"
                    id="new-card-dialog-header"
                    sx={{
                        alignItems: 'center',
                        borderBottom: 1,
                        borderColor: 'divider',
                        display: 'flex',
                        flexShrink: 0,
                        gap: 1.25,
                        minHeight: isMobile ? 56 : 62,
                        px: isMobile ? 1 : 2.25,
                        py: 1,
                    }}
                >
                    {isMobile ? (
                        <Button onClick={handleDialogClose} sx={{ minHeight: 44, minWidth: 72 }} type="button" variant="text">
                            Cancel
                        </Button>
                    ) : (
                        <Box
                            sx={{
                                alignItems: 'center',
                                bgcolor: 'custom.primaryBg',
                                borderRadius: 1,
                                color: 'primary.main',
                                display: 'flex',
                                height: 30,
                                justifyContent: 'center',
                                width: 30,
                            }}
                        >
                            <Plus sx={{ fontSize: 18 }} />
                        </Box>
                    )}
                    <Typography
                        component="h2"
                        id="new-card-dialog-heading"
                        sx={{
                            flex: 1,
                            fontSize: isMobile ? 16 : 15.5,
                            fontWeight: 700,
                            textAlign: isMobile ? 'center' : 'left',
                        }}
                    >
                        New card
                    </Typography>
                    {isMobile ? (
                        <Button disabled={isSubmitDisabled} sx={{ minHeight: 44, minWidth: 72 }} type="submit" variant="text">
                            Create
                        </Button>
                    ) : (
                        <Tooltip title="Close">
                            <IconButton aria-label="Close" onClick={handleDialogClose} size="small" sx={{ height: 30, width: 30 }}>
                                <Close sx={{ fontSize: 17 }} />
                            </IconButton>
                        </Tooltip>
                    )}
                </DialogTitle>
                <DialogContent
                    data-testid="new-card-dialog-content"
                    sx={{
                        display: 'flex',
                        flex: 1,
                        flexDirection: 'column',
                        gap: isMobile ? 2.25 : 2,
                        minHeight: 0,
                        overflowY: 'auto',
                        px: isMobile ? 2 : 2.25,
                        py: isMobile ? 2.25 : 2.25,
                    }}
                >
                    <TextField
                        autoFocus
                        fullWidth
                        id="new-card-title"
                        onChange={handleTitleChange}
                        placeholder="Card titleâ€¦"
                        slotProps={{ htmlInput: { 'aria-label': 'Title' } }}
                        sx={{
                            '& .MuiOutlinedInput-root': {
                                borderRadius: isMobile ? '11px' : '9px',
                                mt: 1,
                                height: isMobile ? 48 : 46,
                                '&.Mui-focused': { boxShadow: (currentTheme) => `0 0 0 3px ${currentTheme.palette.custom.primaryBg}` },
                                '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderWidth: 1 },
                                '& .MuiOutlinedInput-notchedOutline': { borderColor: 'custom.borderStrong' },
                            },
                            '& input': {
                                fontSize: isMobile ? 18 : 17,
                                fontWeight: 600,
                            },
                        }}
                        value={title}
                        variant="outlined"
                    />
                    <CardTypePillGroup
                        cardTypes={cardTypes}
                        isMobile={isMobile}
                        onChange={setType}
                        selectedType={selectedType}
                    />
                    <Stack spacing={isMobile ? 1.125 : 0.875}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                            <Typography color="text.secondary" id="new-card-description-label" sx={{ fontSize: 12, fontWeight: 600 }}>
                                Description
                            </Typography>
                            {!isMobile ? (
                                <Typography color="custom.text3" sx={{ fontSize: 11.5 }}>
                                    Markdown
                                </Typography>
                            ) : null}
                            <Box sx={{ flex: 1 }} />
                            <Button
                                disabled={cardBodyTemplate.length === 0}
                                onClick={handleTemplateClick}
                                size="small"
                                sx={{ minHeight: isMobile ? 44 : 30 }}
                                type="button"
                                variant="outlined"
                            >
                                {templateButtonLabel}
                            </Button>
                        </Stack>
                        <Box
                            aria-labelledby="new-card-description-label"
                            data-testid="new-card-description"
                            role="group"
                            sx={{
                                bgcolor: 'background.paper',
                                border: 1,
                                borderColor: 'custom.borderStrong',
                                borderRadius: isMobile ? '11px' : '9px',
                                boxSizing: 'border-box',
                                color: 'text.primary',
                                height: isMobile ? 260 : 270,
                                minHeight: isMobile ? 260 : 270,
                                outline: 'none',
                                overflow: 'auto',
                                resize: isMobile ? 'none' : 'vertical',
                                width: '100%',
                                '&:focus-within': {
                                    borderColor: 'primary.main',
                                    boxShadow: (currentTheme) => `0 0 0 3px ${currentTheme.palette.custom.primaryBg}`,
                                },
                                '&:hover:not(:focus-within)': { borderColor: 'custom.borderHover' },
                                '& > [data-sticky-toolbar]': { minHeight: '100%' },
                                '& .light-theme, & .dark-theme': { minHeight: '100%' },
                                '& .mdxeditor-content': {
                                    boxSizing: 'border-box',
                                    minHeight: isMobile ? 258 : 268,
                                    p: 1.625,
                                },
                            }}
                        >
                            <NewCardMarkdownEditor
                                onDirtyChange={handleBodyDirtyChange}
                                ref={bodyEditorRef}
                            />
                        </Box>
                    </Stack>
                </DialogContent>
                <DialogActions
                    sx={{
                        alignItems: 'stretch',
                        bgcolor: 'background.default',
                        borderTop: 1,
                        borderColor: 'divider',
                        flexDirection: isMobile ? 'column' : 'row',
                        flexShrink: 0,
                        gap: isMobile ? 1.5 : 1,
                        justifyContent: 'space-between',
                        m: 0,
                        px: isMobile ? 2 : 2.25,
                        py: isMobile ? 1.5 : 1.5,
                        pb: isMobile ? 'max(12px, env(safe-area-inset-bottom))' : 1.5,
                    }}
                >
                    <NewCardColumnPicker
                        isMobile={isMobile}
                        onChange={setTargetStatus}
                        selectedStatus={selectedStatus}
                        states={states}
                    />
                    {isMobile ? createButton : (
                        <Stack direction="row" spacing={1}>
                            <Button onClick={handleDialogClose} type="button" variant="outlined">
                                Cancel
                            </Button>
                            {createButton}
                        </Stack>
                    )}
                </DialogActions>
            </Box>
        </Dialog>
    )
}

import { Box, Typography } from '@mui/material'
import {
    useCallback, useEffect, useRef, useState, useSyncExternalStore,
    type KeyboardEvent, type PointerEvent as ReactPointerEvent, type ReactNode,
} from 'react'
import { ACTION_PROMPT_PLACEHOLDERS } from '../../../data/action_placeholders'
import { dialogService } from '../../../services/dialog_service'
import type { ActionPromptDraft } from '../../../services/actions/action_prompt_draft_service'
import { MarkdownEditor, type MarkdownEditorHandle } from '../../editor/markdown_editor'

const MIN_PROMPT_HEIGHT = 72
const MIN_CHAT_HEIGHT = 96
const DEFAULT_PROMPT_HEIGHT = 140
const EMPTY_PROMPT_EDITOR_HEIGHT = 56
const PROMPT_RESIZE_STEP = 24
const PROMPT_HEIGHT_STORAGE_KEY = 'md2.actionPromptHeight'

function readStoredPromptHeight(): number {
    const storedValue = window.localStorage.getItem(PROMPT_HEIGHT_STORAGE_KEY)
    const parsedValue = storedValue ? Number.parseInt(storedValue, 10) : Number.NaN

    return Number.isNaN(parsedValue) ? DEFAULT_PROMPT_HEIGHT : parsedValue
}

function persistPromptHeight(height: number) {
    window.localStorage.setItem(PROMPT_HEIGHT_STORAGE_KEY, String(Math.round(height)))
}

interface ActionAgentPromptProps {
    attachmentHandler?: (files: File[], insertMarkdown: (markdown: string) => void) => Promise<void>
    bottomRow?: ReactNode
    convertMessage: string | null
    disabled: boolean
    onRunShortcut?: () => void
    promptDraft: ActionPromptDraft
    responsePrompts?: ReactNode
}

/** Resizable prompt editor shown below an agent conversation. */
export function ActionAgentPrompt(props: ActionAgentPromptProps) {
    const {attachmentHandler, bottomRow, convertMessage, disabled, onRunShortcut, promptDraft, responsePrompts} = props
    const promptEditorRef = useRef<MarkdownEditorHandle>(null)
    const promptHeightStartRef = useRef(0)
    const pointerStartYRef = useRef(0)
    const promptSurfaceRef = useRef<HTMLElement | null>(null)
    const [promptHeight, setPromptHeight] = useState(readStoredPromptHeight)
    const [resizingPrompt, setResizingPrompt] = useState(false)
    const prompt = useSyncExternalStore(promptDraft.subscribe, promptDraft.getSnapshot, promptDraft.getSnapshot)
    const editorSnapshot = useSyncExternalStore(
        promptDraft.subscribeEditor,
        promptDraft.getEditorSnapshot,
        promptDraft.getEditorSnapshot,
    )

    useEffect(() => {
        promptEditorRef.current?.setMarkdown(promptDraft.getSnapshot())
    }, [editorSnapshot.replacementRevision, promptDraft])

    const promptEmpty = prompt.trim().length === 0

    const clampPromptHeight = useCallback((proposed: number) => {
        const container = promptSurfaceRef.current?.parentElement
        const available = container ? container.getBoundingClientRect().height - MIN_CHAT_HEIGHT : proposed
        const max = Math.max(MIN_PROMPT_HEIGHT, available)

        return Math.min(Math.max(proposed, MIN_PROMPT_HEIGHT), max)
    }, [])

    const handlePromptSurfaceRef = useCallback((surface: HTMLElement | null) => {
        promptSurfaceRef.current = surface
        if (!surface || promptEmpty) return

        setPromptHeight((height) => {
            const clamped = clampPromptHeight(height)
            if (clamped !== height) persistPromptHeight(clamped)

            return clamped
        })
    }, [clampPromptHeight, promptEmpty])

    const handleLivePromptChange = (value: string) => {
        if (value.trim().length === 0) setResizingPrompt(false)
        promptDraft.edit(value)
    }

    const handlePromptChange = (value: string) => {
        handleLivePromptChange(value)
        void promptDraft.synchronize().catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Could not queue agent prompt' })
        })
    }

    const handleSplitPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (promptEmpty) return

        event.preventDefault()
        promptHeightStartRef.current = promptHeight
        pointerStartYRef.current = event.clientY
        setResizingPrompt(true)
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }

    const handleSplitPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (promptEmpty || !resizingPrompt) return

        const delta = pointerStartYRef.current - event.clientY
        setPromptHeight(clampPromptHeight(promptHeightStartRef.current + delta))
    }

    const handleSplitPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (!resizingPrompt) return

        setResizingPrompt(false)
        event.currentTarget.releasePointerCapture?.(event.pointerId)
        if (promptEmpty) return

        setPromptHeight((height) => {
            persistPromptHeight(height)

            return height
        })
    }

    const handleSplitKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        if (promptEmpty) return

        const nextByKey: Record<string, number> = {
            ArrowDown: promptHeight - PROMPT_RESIZE_STEP,
            ArrowUp: promptHeight + PROMPT_RESIZE_STEP,
        }
        const next = nextByKey[event.key]
        if (next === undefined) return

        event.preventDefault()
        const clamped = clampPromptHeight(next)
        setPromptHeight(clamped)
        persistPromptHeight(clamped)
    }

    const handlePromptKeyDownCapture = (event: KeyboardEvent<HTMLDivElement>) => {
        if (event.key !== 'Enter' || (!event.ctrlKey && !event.metaKey) || !onRunShortcut) return

        event.preventDefault()
        event.stopPropagation()
        promptEditorRef.current?.flush()
        onRunShortcut()
    }

    return (
        <>
            <Box
                aria-label="Resize prompt"
                aria-disabled={promptEmpty ? 'true' : undefined}
                aria-orientation="horizontal"
                aria-valuemin={MIN_PROMPT_HEIGHT}
                aria-valuenow={Math.round(promptHeight)}
                onKeyDown={handleSplitKeyDown}
                onPointerDown={handleSplitPointerDown}
                onPointerMove={handleSplitPointerMove}
                onPointerUp={handleSplitPointerUp}
                role="separator"
                sx={{
                    bgcolor: resizingPrompt && !promptEmpty ? 'primary.main' : 'divider',
                    borderRadius: '2px',
                    cursor: promptEmpty ? 'default' : 'row-resize',
                    flexShrink: 0,
                    height: '3px',
                    mx: 'auto',
                    my: '2px',
                    width: '100%',
                    '&:hover': { bgcolor: promptEmpty ? 'divider' : 'primary.main' },
                }}
                tabIndex={promptEmpty ? -1 : 0}
            />
            <Box
                aria-label="Prompt"
                onKeyDownCapture={handlePromptKeyDownCapture}
                ref={handlePromptSurfaceRef}
                sx={{
                    borderRadius: '9px',
                    border: 1,
                    borderColor: 'custom.borderStrong',
                    display: 'flex',
                    flexDirection: 'column',
                    flexShrink: 0,
                    height: promptEmpty ? 'auto' : promptHeight,
                    overflow: 'hidden',
                    '&:focus-within': {
                        borderColor: 'primary.main',
                        boxShadow: (theme) => `0 0 0 3px ${theme.palette.action.selected}`,
                    },
                }}
            >
                <Box
                    data-testid="action-prompt-editor-region"
                    sx={{
                        flex: promptEmpty ? '0 0 auto' : 1,
                        height: promptEmpty ? EMPTY_PROMPT_EDITOR_HEIGHT : undefined,
                        mb: promptEmpty ? -1.5 : 1,
                        minHeight: 0,
                        overflowY: 'auto',
                        px: 1,
                    }}
                >
                    <MarkdownEditor
                        attachmentHandler={attachmentHandler}
                        flushOnBlur
                        hideToolbar
                        localTextSearch={false}
                        markdown={prompt}
                        onChange={handlePromptChange}
                        onLiveChange={handleLivePromptChange}
                        placeholders={ACTION_PROMPT_PLACEHOLDERS}
                        readOnly={disabled || editorSnapshot.preparationStatus !== 'ready'}
                        ref={promptEditorRef}
                    />
                </Box>
                {responsePrompts}
                {bottomRow}
            </Box>
            {convertMessage ? (
                <Typography color="text.secondary" role="status" variant="caption">
                    {convertMessage}
                </Typography>
            ) : null}
        </>
    )
}

import { useCallback, useEffect, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import type { ActionDefinition } from '../../../data/action_types'
import type { ActionRun } from '../../../services/actions/action_run_registry'
import type { ActionRunSettingsStore } from '../../../services/actions/action_run_settings_service'
import { dialogService } from '../../../services/dialog_service'
import { remoteConnectionService } from '../../../services/data/remote_connection_service'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import { ActionAgentPrompt } from './action_agent_prompt'
import type { ActionConversationStore } from '../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../run/state/action_history_store'
import { currentActionPromptDraft, runPopupAction } from '../run/popup/action_popup_operations'
import { actionPopupRunDisabled } from '../run/popup/action_popup_run_disabled'
import type { ActionRunInputStore } from '../run/state/action_run_input_store'
import type { ActionRunResultStore } from '../run/state/action_run_result_store'
import type { ActionScheduleStore } from '../run/schedule/action_schedule_store'
import { defaultPreparePrompt } from '../run/popup/action_popup_defaults'
import { ActionPopupBottomRow } from '../run/popup/action_popup_bottom_row'
import type { ActionUsageScopeStore } from '../run/popup/action_usage_scope_store'
import { useActionRunSettings } from '../shared/use_action_run_settings'
import { ActionPhraseButtonsOwner } from '../editor/action_phrase_buttons_owner'

interface ActionAgentPromptOwnerProps {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    scheduleStore: ActionScheduleStore
    settingsStore: ActionRunSettingsStore
    usageScopeStore: ActionUsageScopeStore
}

function selectSessionActive(run: ActionRun | null) {
    return run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
}

/** Owns prompt draft binding, preparation, and keyboard-run behavior. */
export function ActionAgentPromptOwner(props: ActionAgentPromptOwnerProps) {
    const {
        action, context, conversationStore, historyStore, inputStore, resultStore, runValidationError,
        scheduleStore, settingsStore, usageScopeStore,
    } = props
    const sessionActive = useActionRunSelector(action.id, context, selectSessionActive)
    const activeActionType = useActionRunSelector(action.id, context, (run) => run?.activeActionType ?? null)
    const hasApprovals = useActionRunSelector(action.id, context, (run) => !!run?.approvals.length)
    const hasQuestion = useActionRunSelector(action.id, context, (run) => !!run?.question)
    const interactionReady = useActionRunSelector(action.id, context, (run) => !!run?.interactionReady)
    const runStatus = useActionRunSelector(action.id, context, (run) => run?.status ?? 'idle')
    const conversationSnapshot = useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const inputSnapshot = useSyncExternalStore(inputStore.subscribe, inputStore.getSnapshot, inputStore.getSnapshot)
    const remoteConnection = useSyncExternalStore(
        remoteConnectionService.subscribe,
        remoteConnectionService.getSnapshot,
        remoteConnectionService.getSnapshot,
    )
    const settings = useActionRunSettings(action, settingsStore)
    const prepare = action.type === 'agent'
        && !sessionActive
        && runStatus !== 'completed'
        && conversationSnapshot.selectedConversation === null
    const promptDraft = currentActionPromptDraft(action, context, prepare)
    const handleAttachments = useCallback(async (files: File[], insertMarkdown: (markdown: string) => void) => {
        if ((context.kind !== 'card' && context.kind !== 'file') || !context.file) {
            throw new Error('Card action prompt attachments require a selected card')
        }

        const { attachFilesToCardMarkdown } = await import('../../../services/attachments/attachment_workflow')
        await attachFilesToCardMarkdown(context.file, files, insertMarkdown)
    }, [context])
    const attachmentHandler = (context.kind === 'card' || context.kind === 'file') && context.file
        ? handleAttachments
        : undefined

    useEffect(() => {
        if (!prepare || remoteConnection.status === 'connecting' || remoteConnection.status === 'reconnecting') return

        void promptDraft.prepare(() => defaultPreparePrompt(action, context)).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Could not prepare action prompt' })
        })
    }, [action, context, prepare, promptDraft, remoteConnection.status])

    const handleRunShortcut = () => {
        const prompt = promptDraft.getSnapshot()
        const runState = {
            agentActive: sessionActive && activeActionType === 'agent',
            hasApprovals,
            hasQuestion,
            interactionReady,
            runDisabledMessage: settings.runDisabledMessage,
            runStatus,
        }
        if (actionPopupRunDisabled(
            action,
            runState,
            prompt,
            promptDraft.getEditorSnapshot().preparationStatus,
        )) return

        const operationInput = {
            action,
            context,
            conversationStore,
            historyStore,
            inputStore,
            resultStore,
            runValidationError,
            settings,
            settingsStore,
        }
        void runPopupAction(operationInput)
    }

    return (
        <ActionAgentPrompt
            attachmentHandler={attachmentHandler}
            bottomRow={action.type === 'agent' || activeActionType === 'agent' ? (
                <ActionPopupBottomRow
                    action={action}
                    assignmentContext={context}
                    conversationStore={conversationStore}
                    embedded
                    historyStore={historyStore}
                    inputStore={inputStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                    settingsStore={settingsStore}
                    usageScopeStore={usageScopeStore}
                />
            ) : undefined}
            convertMessage={inputSnapshot.convertMessage}
            disabled={false}
            onRunShortcut={handleRunShortcut}
            promptDraft={promptDraft}
            responsePrompts={(
                <ActionPhraseButtonsOwner
                    action={action}
                    context={context}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    settingsStore={settingsStore}
                />
            )}
        />
    )
}

