        expect(screen.getByTestId('action-popup-bottom-row')).not.toHaveAttribute('data-embedded')

        fireEvent.mouseOver(run)
        expect(await screen.findByText('Run', { selector: '.MuiTooltip-tooltip' })).toBeInTheDocument()
