import { Box } from '@mui/material'
import {
    MDXEditor, codeBlockPlugin, codeMirrorPlugin, diffSourcePlugin,
    headingsPlugin, imagePlugin, linkDialogPlugin, linkPlugin, listsPlugin, markdownShortcutPlugin, quotePlugin,
    tablePlugin, thematicBreakPlugin, toolbarPlugin,
    type MDXEditorMethods, type ViewMode,
} from '@mdxeditor/editor'
import '@mdxeditor/editor/style.css'
import {
    forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef,
    type DragEvent, type FocusEvent, type ReactNode,
} from 'react'
import type { ActionPlaceholder } from '../../data/action_placeholders'
import { useProjectState } from '../hooks/use_project_state'
import { dialogService } from '../../services/dialog_service'
import { useAppTheme } from '../../theme/use_app_theme'
import { markdownDocumentHistoryPlugin } from './markdown_document_history_realm_plugin'
import type { MarkdownDocumentHistoryStore } from './markdown_document_history_store'
import { MarkdownFormatToolbarControls } from './markdown_format_toolbar_controls'
import { markdownFileSearchPlugin } from './markdown_file_search_realm_plugin'
import { markdownLocalTextSearchPlugin } from './markdown_local_text_search_realm_plugin'
import { plainMarkdownPlugin } from './plain_markdown_realm_plugin'
import { markdownPlaceholderPlugin } from './markdown_placeholder_realm_plugin'
import { registerMarkdownEditorStage } from '../../services/project/markdown_editor_staging'
import { markdownPastePlugin } from './markdown_paste_realm_plugin'
import type { MarkdownImagePasteHandler } from './markdown_paste_cell'
import type {
    ActiveMarkdownDocumentChangedDetail,
    MarkdownBindingKind,
    MarkdownDataSource,
    MarkdownDocumentTarget,
} from './markdown_data_source'
import { MarkdownAttachmentToolbarControl } from './markdown_attachment_toolbar_control'
import type { AttachmentMarkdownInserter } from '../../services/attachments/attachment_workflow'

const DEFAULT_CODE_LANGUAGE = ''
const CODE_BLOCK_LANGUAGES = { '': 'Plain text', js: 'JavaScript', ts: 'TypeScript', tsx: 'TSX', bash: 'Shell' }
const EMPTY_PLACEHOLDERS: readonly ActionPlaceholder[] = []
const EMPTY_REPOSITORY_FILES: readonly string[] = []

export interface MarkdownEditorHandle {
    flush(): boolean
    getMarkdown(): string
    setMarkdown(markdown: string): void
}

interface MarkdownEditorPresentationProps {
    attachmentHandler?: (files: File[], insertMarkdown: AttachmentMarkdownInserter) => Promise<void>
    diffMarkdown?: string
    flushOnBlur?: boolean
    /** Omit format toolbar entirely. */
    hideToolbar?: boolean
    imagePasteHandler?: MarkdownImagePasteHandler
    /** Set false when containing surface owns Ctrl+F behavior. */
    localTextSearch?: boolean
    overlayContainer?: HTMLElement | null
    placeholders?: readonly ActionPlaceholder[]
    readOnly?: boolean
    toolbarContents?: () => ReactNode
    viewMode?: ViewMode
}

interface MarkdownEditorDataSourceProps extends MarkdownEditorPresentationProps {
    binding: MarkdownBindingKind
    dataSource: MarkdownDataSource
    historyStore: MarkdownDocumentHistoryStore
    markdown?: never
    onChange?: never
    onDirtyChange?: never
    onLiveChange?: never
}

interface MarkdownEditorLocalProps extends MarkdownEditorPresentationProps {
    binding?: never
    dataSource?: never
    historyStore?: never
    markdown: string
    onChange: (markdown: string) => void
    onDirtyChange?: (dirty: boolean) => void
    onLiveChange?: (markdown: string) => void
}

type MarkdownEditorProps = MarkdownEditorDataSourceProps | MarkdownEditorLocalProps

interface MarkdownDocumentSnapshot {
    target: MarkdownDocumentTarget | null
    markdown: string
}

interface MarkdownProcessingError {
    error: string
}

function initialDocument(props: MarkdownEditorProps): MarkdownDocumentSnapshot {
    if (!props.dataSource) return { target: null, markdown: props.markdown }

    const target = props.dataSource.getActiveTarget(props.binding)
    return { target, markdown: target ? props.dataSource.getMarkdown(target) : '' }
}

/** Reusable MDXEditor surface with local-buffer and persisted data-source modes. */
export const MarkdownEditor = forwardRef<MarkdownEditorHandle, MarkdownEditorProps>(function MarkdownEditor(props, ref) {
    const {
        flushOnBlur = false,
        attachmentHandler,
        diffMarkdown,
        hideToolbar = false,
        imagePasteHandler,
        localTextSearch = true,
        overlayContainer,
        placeholders = EMPTY_PLACEHOLDERS,
        readOnly = false,
        toolbarContents: customToolbarContents,
        viewMode,
    } = props
    const dataSource = props.dataSource
    const binding = props.binding
    const historyStore = props.historyStore
    const { snapshot } = useProjectState()
    const repositoryFiles = snapshot?.repositoryFiles ?? EMPTY_REPOSITORY_FILES
    const initialDocumentRef = useRef<MarkdownDocumentSnapshot | null>(null)
    if (!initialDocumentRef.current) initialDocumentRef.current = initialDocument(props)
    const initialDocumentSnapshot = initialDocumentRef.current
    const { markdownContentSx, mode } = useAppTheme()
    const editorRef = useRef<MDXEditorMethods>(null)
    const activeTargetRef = useRef(initialDocumentSnapshot.target)
    const latestMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const lastEmittedMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const dirtyBaselineEstablishedRef = useRef(false)
    const missingEditorReportedRef = useRef(false)
    const replacingMarkdownRef = useRef(false)
    const onChangeRef = useRef(props.onChange)
    const onDirtyChangeRef = useRef(props.onDirtyChange)
    const onLiveChangeRef = useRef(props.onLiveChange)
    const applyPendingDocumentChangeRef = useRef<() => void>(() => undefined)
    onChangeRef.current = props.onChange
    onDirtyChangeRef.current = props.onDirtyChange
    onLiveChangeRef.current = props.onLiveChange

    const setDirty = useCallback((dirty: boolean) => {
        onDirtyChangeRef.current?.(dirty)
    }, [])

    const flush = useCallback(() => {
        if (latestMarkdownRef.current === lastEmittedMarkdownRef.current) return true

        const activeTarget = activeTargetRef.current
        if (dataSource && binding) {
            if (!activeTarget) return false
            const committed = dataSource.commit(binding, activeTarget, latestMarkdownRef.current)
            if (!committed) return false
        } else {
            onChangeRef.current?.(latestMarkdownRef.current)
        }
        lastEmittedMarkdownRef.current = latestMarkdownRef.current
        setDirty(false)
        queueMicrotask(() => applyPendingDocumentChangeRef.current())

        return true
    }, [binding, dataSource, setDirty])

    const prepareDocumentSwitch = useCallback((detail: ActiveMarkdownDocumentChangedDetail, nextMarkdown: string) => {
        if (detail.discard) lastEmittedMarkdownRef.current = latestMarkdownRef.current
        if (!flush()) return null

        const currentMarkdown = latestMarkdownRef.current
        activeTargetRef.current = detail.target
        latestMarkdownRef.current = nextMarkdown
        lastEmittedMarkdownRef.current = nextMarkdown
        setDirty(false)

        return currentMarkdown
    }, [flush, setDirty])

    const completeDocumentSwitch = useCallback((normalizedMarkdown: string) => {
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        setDirty(false)
    }, [setDirty])

    const getMarkdown = useCallback(() => editorRef.current?.getMarkdown() ?? latestMarkdownRef.current, [])
    const getTarget = useCallback(() => activeTargetRef.current, [])

    const replaceMarkdown = useCallback((markdown: string) => {
        replacingMarkdownRef.current = true
        editorRef.current?.setMarkdown(markdown)
        replacingMarkdownRef.current = false
    }, [])

    const setPendingDocumentChangeRetry = useCallback((retry: () => void) => {
        applyPendingDocumentChangeRef.current = retry
    }, [])

    const historyPluginConfig = useMemo(() => historyStore && binding && dataSource
        ? {
            binding,
            completeDocumentSwitch,
            dataSource,
            getTarget,
            getMarkdown,
            historyStore,
            prepareDocumentSwitch,
            replaceMarkdown,
            setPendingDocumentChangeRetry,
        }
        : null, [
        binding,
        completeDocumentSwitch,
        dataSource,
        getTarget,
        getMarkdown,
        historyStore,
        prepareDocumentSwitch,
        replaceMarkdown,
        setPendingDocumentChangeRetry,
    ])

    useEffect(() => {
        if (!editorRef.current) {
            if (!missingEditorReportedRef.current) {
                missingEditorReportedRef.current = true
                dialogService.error(new Error('Cannot baseline markdown before editor is mounted'), {fallbackMessage: 'Markdown editor could not be initialized'})
            }
            return
        }

        const normalizedMarkdown = editorRef.current.getMarkdown()
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        dirtyBaselineEstablishedRef.current = true
    }, [])

    useEffect(() => {
        const unregister = registerMarkdownEditorStage(flush)

        return () => {
            unregister()
            flush()
        }
    }, [flush])

    useImperativeHandle(ref, () => ({
        flush,
        getMarkdown: () => latestMarkdownRef.current,
        setMarkdown: (markdown: string) => {
            replaceMarkdown(markdown)
            latestMarkdownRef.current = markdown
            lastEmittedMarkdownRef.current = markdown
            setDirty(false)
        },
    }), [flush, replaceMarkdown, setDirty])

    const handleEditorChange = useCallback((markdown: string) => {
        if (replacingMarkdownRef.current || latestMarkdownRef.current === markdown) return

        latestMarkdownRef.current = markdown
        if (!dirtyBaselineEstablishedRef.current) return
        setDirty(markdown !== lastEmittedMarkdownRef.current)
        onLiveChangeRef.current?.(markdown)
        const activeTarget = activeTargetRef.current
        if (dataSource && binding && activeTarget) dataSource.edit(binding, activeTarget, markdown)
    }, [binding, dataSource, setDirty])

    const handleEditorError = useCallback(({ error }: MarkdownProcessingError) => {
        dialogService.error(new Error(error), { fallbackMessage: 'Markdown could not be parsed' })
    }, [])

    const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
        if (!flushOnBlur || event.currentTarget.contains(event.relatedTarget)) return
        flush()
    }

    const insertMarkdown = useCallback((markdown: string) => {
        editorRef.current?.insertMarkdown(markdown)
    }, [])

    const getSelectionMarkdown = useCallback(() => editorRef.current?.getSelectionMarkdown() ?? '', [])

    const attachFiles = useCallback((files: File[]) => {
        if (!attachmentHandler || readOnly || files.length === 0) return
        void attachmentHandler(files, insertMarkdown).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Files could not be attached' })
        })
    }, [attachmentHandler, insertMarkdown, readOnly])

    const handleDragOverCapture = (event: DragEvent<HTMLDivElement>) => {
        if (!attachmentHandler || readOnly || !event.dataTransfer.types.includes('Files')) return
        event.preventDefault()
        event.stopPropagation()
    }

    const handleDropCapture = (event: DragEvent<HTMLDivElement>) => {
        if (!attachmentHandler || readOnly || !event.dataTransfer.types.includes('Files')) return
        event.preventDefault()
        event.stopPropagation()
        attachFiles([...event.dataTransfer.files])
    }

    const toolbarContents = useCallback(() => (
        <>
            {!hideToolbar ? (
                customToolbarContents?.()
                ?? (
                    <MarkdownFormatToolbarControls
                        overlayContainer={overlayContainer}
                        placeholders={placeholders}
                        readOnly={readOnly}
                    />
                )
            ) : null}
            {attachmentHandler ? <MarkdownAttachmentToolbarControl disabled={readOnly} onFiles={attachFiles} /> : null}
        </>
    ), [attachFiles, attachmentHandler, customToolbarContents, hideToolbar, overlayContainer, placeholders, readOnly])
    const editorSx = {
        ...markdownContentSx,
        '& .mdxeditor-toolbar': { bgcolor: 'background.paper', position: 'sticky', top: 0, zIndex: 1 },
    }
    const historyPlugin = historyPluginConfig ? markdownDocumentHistoryPlugin(historyPluginConfig) : null
    const plugins = [
        headingsPlugin(),
        listsPlugin(),
        quotePlugin(),
        thematicBreakPlugin(),
        linkPlugin(),
        linkDialogPlugin(),
        imagePlugin(),
        tablePlugin(),
        codeBlockPlugin({ defaultCodeBlockLanguage: DEFAULT_CODE_LANGUAGE }),
        codeMirrorPlugin({ codeBlockLanguages: CODE_BLOCK_LANGUAGES }),
        markdownShortcutPlugin(),
        plainMarkdownPlugin(),
        ...(viewMode ? [diffSourcePlugin({ diffMarkdown: diffMarkdown ?? '', viewMode })] : []),
        ...(!hideToolbar || attachmentHandler ? [toolbarPlugin({ toolbarContents })] : []),
        markdownPlaceholderPlugin({ overlayContainer, placeholders }),
        markdownFileSearchPlugin({ overlayContainer, repositoryFiles }),
        ...(localTextSearch ? [markdownLocalTextSearchPlugin({ overlayContainer })] : []),
        markdownPastePlugin({ getSelectionMarkdown, imagePasteHandler, insertMarkdown, readOnly }),
        ...(historyPlugin ? [historyPlugin] : []),
    ]

    return (
        <Box
            data-sticky-toolbar
            onBlur={handleBlur}
            onDragOverCapture={handleDragOverCapture}
            onDropCapture={handleDropCapture}
            sx={editorSx}
        >
            <MDXEditor
                className={mode === 'dark' ? 'dark-theme' : 'light-theme'}
                contentEditableClassName="mdxeditor-content"
                markdown={initialDocumentSnapshot.markdown}
                onChange={handleEditorChange}
                onError={handleEditorError}
                overlayContainer={overlayContainer}
                plugins={plugins}
                readOnly={readOnly}
                ref={editorRef}
                suppressHtmlProcessing
                suppressSharedHistory={!!historyStore}
            />
        </Box>
    )
})

import { IconButton, Tooltip } from '@mui/material'
import Paperclip from 'mdi-material-ui/Paperclip'
import { useRef, type ChangeEvent } from 'react'

interface MarkdownAttachmentToolbarControlProps {
    disabled: boolean
    onFiles: (files: File[]) => void
}

/** Paperclip file picker shared by writable Markdown editor toolbars. */
export function MarkdownAttachmentToolbarControl(props: MarkdownAttachmentToolbarControlProps) {
    const { disabled, onFiles } = props
    const inputRef = useRef<HTMLInputElement>(null)
    const openFilePicker = () => inputRef.current?.click()
    const handleFilesSelected = (event: ChangeEvent<HTMLInputElement>) => {
        const files = [...(event.target.files ?? [])]
        event.target.value = ''
        if (files.length > 0) onFiles(files)
    }

    return (
        <>
            <Tooltip title="Attach files">
                <span>
                    <IconButton aria-label="Attach files" disabled={disabled} onClick={openFilePicker} size="small">
                        <Paperclip sx={{ fontSize: 18 }} />
                    </IconButton>
                </span>
            </Tooltip>
            <input hidden multiple onChange={handleFilesSelected} ref={inputRef} type="file" />
        </>
    )
}

import { actionContextIdentity, type ActionContext } from '../../data/action_context'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import type { ActionDefinition } from '../../data/action_types'
import { isRemoteControlConnectionError } from '../data/remote_control_storage_service'
import { register } from '../service_injector'

export type ActionPromptPreparationStatus = 'failed' | 'loading' | 'ready'

export interface ActionPromptRunBinding {
    activeActionId: string | null
    activeActionType: ActionDefinition['type'] | null
    runId: string
    interactionReady: boolean
    rootActionId: string
}

interface ActionPromptDraftEditorSnapshot {
    preparationStatus: ActionPromptPreparationStatus
    replacementRevision: number
}

interface ActionPromptDraftOptions {
    initialValue?: string
    prepare: boolean
}

type ActionPromptDraftListener = () => void

function idlePromptDraftKey(actionId: string, context: ActionContext) {
    return `idle\u0000${actionId}\u0000${actionContextIdentity(context)}`
}

function runPromptDraftKey(runId: string, actionId: string) {
    return `run\u0000${runId}\u0000${actionId}`
}

async function beginActionPromptDraft(runId: string) {
    const bridge = getElectronActionBridge()
    if (!bridge?.beginActionPromptDraft) throw new Error('Agent prompt queue requires Electron')

    return bridge.beginActionPromptDraft(runId)
}

async function setActionQueuedMessage(runId: string, sessionId: number, content: string, revision: number) {
    const bridge = getElectronActionBridge()
    if (!bridge?.setActionQueuedMessage) throw new Error('Agent prompt queue requires Electron')

    const result = await bridge.setActionQueuedMessage(runId, sessionId, content, revision)
    if (!result.accepted) throw new Error('Queued agent prompt was superseded')
}

async function sendActionQueuedMessage(runId: string, sessionId: number, revision: number) {
    const bridge = getElectronActionBridge()
    if (!bridge?.sendActionQueuedMessage) throw new Error('Sending queued agent prompt requires Electron')

    const result = await bridge.sendActionQueuedMessage(runId, sessionId, revision)
    if (!result.sent) throw new Error('Queued agent prompt was not sent')
}

/** Stable prompt state shared by editor and prompt-dependent leaf controls. */
export class ActionPromptDraft {
    private editorSnapshot: ActionPromptDraftEditorSnapshot
    private readonly editorListeners = new Set<ActionPromptDraftListener>()
    private locallyEdited = false
    private run: ActionPromptRunBinding | null
    private pendingWrite: Promise<void> = Promise.resolve()
    private preparationRequired: boolean
    private preparationStarted = false
    private promptSession: Promise<number> | null = null
    private revision = 0
    private readonly valueListeners = new Set<ActionPromptDraftListener>()
    private value: string

    constructor(
        initialValue: string,
        preparationRequired: boolean,
        run: ActionPromptRunBinding | null,
    ) {
        this.editorSnapshot = {
            preparationStatus: preparationRequired ? 'loading' : 'ready',
            replacementRevision: 0,
        }
        this.run = run
        this.preparationRequired = preparationRequired
        this.value = initialValue
    }

    readonly getSnapshot = () => this.value

    readonly getEditorSnapshot = () => this.editorSnapshot

    readonly subscribe = (listener: ActionPromptDraftListener) => {
        this.valueListeners.add(listener)

        return () => this.valueListeners.delete(listener)
    }

    readonly subscribeEditor = (listener: ActionPromptDraftListener) => {
        this.editorListeners.add(listener)

        return () => this.editorListeners.delete(listener)
    }

    bindRun(run: ActionPromptRunBinding | null) {
        this.run = run
    }

    /** Record an editor-local value without starting asynchronous synchronization. */
    readonly edit = (value: string) => {
        this.revision += 1
        this.locallyEdited = true
        this.preparationRequired = false
        this.setPreparationStatus('ready')
        this.setValue(value)
    }

    /** Replace editor content from an external source and notify editor exactly once. */
    replace(value: string) {
        this.revision += 1
        this.locallyEdited = false
        this.preparationRequired = false
        this.setValue(value)
        this.editorSnapshot = {
            preparationStatus: 'ready',
            replacementRevision: this.editorSnapshot.replacementRevision + 1,
        }
        this.publishEditor()
    }

    clear() {
        if (this.value.length === 0 && this.editorSnapshot.preparationStatus === 'ready') return

        this.replace('')
    }

    async prepare(load: () => Promise<string>) {
        if (!this.preparationRequired || this.preparationStarted) return

        this.preparationStarted = true
        const preparationRevision = this.revision
        try {
            const value = await load()
            if (this.revision !== preparationRevision) return

            this.replace(value)
        } catch (error) {
            if (this.revision !== preparationRevision) return

            if (isRemoteControlConnectionError(error)) {
                this.preparationStarted = false
                this.setPreparationStatus('loading')

                return
            }

            this.preparationRequired = false
            this.setPreparationStatus('failed')
            throw error
        }
    }

    hasLocalEdits() {
        return this.locallyEdited
    }

    async synchronize() {
        const run = this.run
        if (!run?.interactionReady || run.activeActionType !== 'agent' || !run.activeActionId) return

        const value = this.value
        const revision = this.revision
        const pendingWrite = this.pendingWrite.catch(() => undefined).then(async () => {
            const sessionId = await this.getPromptSession(run.runId)
            await setActionQueuedMessage(run.runId, sessionId, value, revision)
        })
        this.pendingWrite = pendingWrite

        try {
            await pendingWrite
        } catch (error) {
            this.promptSession = null
            throw error
        }
    }

    async send() {
        const run = this.run
        if (!run?.activeActionId) throw new Error('Action run has no active agent')
        if (this.value.trim().length === 0) throw new Error('Queued agent prompt is empty')

        await this.pendingWrite
        const value = this.value
        const revision = this.revision
        const sessionId = await this.getPromptSession(run.runId)
        try {
            await setActionQueuedMessage(run.runId, sessionId, value, revision)
            await sendActionQueuedMessage(run.runId, sessionId, revision)
            this.clear()
        } catch (error) {
            this.promptSession = null
            throw error
        }
    }

    private getPromptSession(runId: string) {
        if (this.promptSession) return this.promptSession

        const promptSession = beginActionPromptDraft(runId).catch((error: unknown) => {
            this.promptSession = null
            throw error
        })
        this.promptSession = promptSession

        return promptSession
    }

    private setValue(value: string) {
        if (this.value === value) return

        this.value = value
        for (const listener of this.valueListeners) listener()
    }

    private setPreparationStatus(preparationStatus: ActionPromptPreparationStatus) {
        if (this.editorSnapshot.preparationStatus === preparationStatus) return

        this.editorSnapshot = { ...this.editorSnapshot, preparationStatus }
        this.publishEditor()
    }

    private publishEditor() {
        for (const listener of this.editorListeners) listener()
    }
}

/** Owns lifetime-stable prompt drafts, remote sessions, revisions, and explicit cleanup. */
export class ActionPromptDraftService {
    private readonly drafts = new Map<string, ActionPromptDraft>()

    constructor() {
        register('actionPromptDraftService', this)
    }

    getDraft(
        actionId: string,
        context: ActionContext,
        run: ActionPromptRunBinding | null,
        options: ActionPromptDraftOptions,
    ) {
        const activeRun = run?.rootActionId === actionId
            && run.activeActionType === 'agent'
            && run.activeActionId
            ? run
            : null
        const key = activeRun
            ? runPromptDraftKey(activeRun.runId, activeRun.activeActionId as string)
            : idlePromptDraftKey(actionId, context)
        const current = this.drafts.get(key)
        if (current) {
            current.bindRun(activeRun)

            return current
        }

        const draft = new ActionPromptDraft(options.initialValue ?? '', options.prepare, activeRun)
        this.drafts.set(key, draft)

        return draft
    }

    clearDraft(actionId: string, context: ActionContext, run: ActionPromptRunBinding | null) {
        const activeActionId = run?.rootActionId === actionId ? run.activeActionId : null
        if (activeActionId && run) this.clearByKey(runPromptDraftKey(run.runId, activeActionId))
        this.clearByKey(idlePromptDraftKey(actionId, context))
    }

    clearRunDraft(runId: string, actionId: string) {
        this.clearByKey(runPromptDraftKey(runId, actionId))
    }

    clearRunDrafts(runId: string) {
        const prefix = `run\u0000${runId}\u0000`
        for (const key of this.drafts.keys()) {
            if (key.startsWith(prefix)) this.clearByKey(key)
        }
    }

    clearAction(actionId: string) {
        const idlePrefix = `idle\u0000${actionId}\u0000`
        const runSuffix = `\u0000${actionId}`
        for (const key of this.drafts.keys()) {
            if (key.startsWith(idlePrefix) || (key.startsWith('run\u0000') && key.endsWith(runSuffix))) {
                this.clearByKey(key)
            }
        }
    }

    /** Drop cached prepared defaults while preserving user edits and active-run drafts. */
    invalidateIdlePreparedDrafts(actionId: string) {
        const idlePrefix = `idle\u0000${actionId}\u0000`
        for (const [key, draft] of this.drafts) {
            if (key.startsWith(idlePrefix) && !draft.hasLocalEdits()) this.drafts.delete(key)
        }
    }

    clearAll() {
        for (const draft of this.drafts.values()) draft.clear()
        this.drafts.clear()
    }

    private clearByKey(key: string) {
        const draft = this.drafts.get(key)
        if (!draft) return

        draft.clear()
        this.drafts.delete(key)
    }
}

export const actionPromptDraftService = new ActionPromptDraftService()

import { Box, Typography } from '@mui/material'
import {
    useCallback, useEffect, useRef, useState, useSyncExternalStore,
    type KeyboardEvent, type PointerEvent as ReactPointerEvent, type ReactNode,
} from 'react'
import { ACTION_PROMPT_PLACEHOLDERS } from '../../../data/action_placeholders'
import { dialogService } from '../../../services/dialog_service'
import type { ActionPromptDraft } from '../../../services/actions/action_prompt_draft_service'
import { MarkdownEditor, type MarkdownEditorHandle } from '../../editor/markdown_editor'

const MIN_PROMPT_HEIGHT = 72
const MIN_CHAT_HEIGHT = 96
const DEFAULT_PROMPT_HEIGHT = 140
const EMPTY_PROMPT_EDITOR_HEIGHT = 56
const PROMPT_RESIZE_STEP = 24
const PROMPT_HEIGHT_STORAGE_KEY = 'md2.actionPromptHeight'

function readStoredPromptHeight(): number {
    const storedValue = window.localStorage.getItem(PROMPT_HEIGHT_STORAGE_KEY)
    const parsedValue = storedValue ? Number.parseInt(storedValue, 10) : Number.NaN

    return Number.isNaN(parsedValue) ? DEFAULT_PROMPT_HEIGHT : parsedValue
}

function persistPromptHeight(height: number) {
    window.localStorage.setItem(PROMPT_HEIGHT_STORAGE_KEY, String(Math.round(height)))
}

interface ActionAgentPromptProps {
    attachmentHandler?: (files: File[], insertMarkdown: (markdown: string) => void) => Promise<void>
    bottomRow?: ReactNode
    convertMessage: string | null
    disabled: boolean
    onRunShortcut?: () => void
    promptDraft: ActionPromptDraft
    responsePrompts?: ReactNode
}

/** Resizable prompt editor shown below an agent conversation. */
export function ActionAgentPrompt(props: ActionAgentPromptProps) {
    const {attachmentHandler, bottomRow, convertMessage, disabled, onRunShortcut, promptDraft, responsePrompts} = props
    const promptEditorRef = useRef<MarkdownEditorHandle>(null)
    const promptHeightStartRef = useRef(0)
    const pointerStartYRef = useRef(0)
    const promptSurfaceRef = useRef<HTMLElement | null>(null)
    const [promptHeight, setPromptHeight] = useState(readStoredPromptHeight)
    const [resizingPrompt, setResizingPrompt] = useState(false)
    const prompt = useSyncExternalStore(promptDraft.subscribe, promptDraft.getSnapshot, promptDraft.getSnapshot)
    const editorSnapshot = useSyncExternalStore(
        promptDraft.subscribeEditor,
        promptDraft.getEditorSnapshot,
        promptDraft.getEditorSnapshot,
    )

    useEffect(() => {
        promptEditorRef.current?.setMarkdown(promptDraft.getSnapshot())
    }, [editorSnapshot.replacementRevision, promptDraft])

    const promptEmpty = prompt.trim().length === 0

    const clampPromptHeight = useCallback((proposed: number) => {
        const container = promptSurfaceRef.current?.parentElement
        const available = container ? container.getBoundingClientRect().height - MIN_CHAT_HEIGHT : proposed
        const max = Math.max(MIN_PROMPT_HEIGHT, available)

        return Math.min(Math.max(proposed, MIN_PROMPT_HEIGHT), max)
    }, [])

    const handlePromptSurfaceRef = useCallback((surface: HTMLElement | null) => {
        promptSurfaceRef.current = surface
        if (!surface || promptEmpty) return

        setPromptHeight((height) => {
            const clamped = clampPromptHeight(height)
            if (clamped !== height) persistPromptHeight(clamped)

            return clamped
        })
    }, [clampPromptHeight, promptEmpty])

    const handleLivePromptChange = (value: string) => {
        if (value.trim().length === 0) setResizingPrompt(false)
        promptDraft.edit(value)
    }

    const handlePromptChange = (value: string) => {
        handleLivePromptChange(value)
        void promptDraft.synchronize().catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Could not queue agent prompt' })
        })
    }

    const handleSplitPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (promptEmpty) return

        event.preventDefault()
        promptHeightStartRef.current = promptHeight
        pointerStartYRef.current = event.clientY
        setResizingPrompt(true)
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }

    const handleSplitPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (promptEmpty || !resizingPrompt) return

        const delta = pointerStartYRef.current - event.clientY
        setPromptHeight(clampPromptHeight(promptHeightStartRef.current + delta))
    }

    const handleSplitPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (!resizingPrompt) return

        setResizingPrompt(false)
        event.currentTarget.releasePointerCapture?.(event.pointerId)
        if (promptEmpty) return

        setPromptHeight((height) => {
            persistPromptHeight(height)

            return height
        })
    }

    const handleSplitKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        if (promptEmpty) return

        const nextByKey: Record<string, number> = {
            ArrowDown: promptHeight - PROMPT_RESIZE_STEP,
            ArrowUp: promptHeight + PROMPT_RESIZE_STEP,
        }
        const next = nextByKey[event.key]
        if (next === undefined) return

        event.preventDefault()
        const clamped = clampPromptHeight(next)
        setPromptHeight(clamped)
        persistPromptHeight(clamped)
    }

    const handlePromptKeyDownCapture = (event: KeyboardEvent<HTMLDivElement>) => {
        if (event.key !== 'Enter' || (!event.ctrlKey && !event.metaKey) || !onRunShortcut) return

        event.preventDefault()
        event.stopPropagation()
        promptEditorRef.current?.flush()
        onRunShortcut()
    }

    return (
        <>
            <Box
                aria-label="Resize prompt"
                aria-disabled={promptEmpty ? 'true' : undefined}
                aria-orientation="horizontal"
                aria-valuemin={MIN_PROMPT_HEIGHT}
                aria-valuenow={Math.round(promptHeight)}
                onKeyDown={handleSplitKeyDown}
                onPointerDown={handleSplitPointerDown}
                onPointerMove={handleSplitPointerMove}
                onPointerUp={handleSplitPointerUp}
                role="separator"
                sx={{
                    bgcolor: resizingPrompt && !promptEmpty ? 'primary.main' : 'divider',
                    borderRadius: '2px',
                    cursor: promptEmpty ? 'default' : 'row-resize',
                    flexShrink: 0,
                    height: '3px',
                    mx: 'auto',
                    my: '2px',
                    width: '100%',
                    '&:hover': { bgcolor: promptEmpty ? 'divider' : 'primary.main' },
                }}
                tabIndex={promptEmpty ? -1 : 0}
            />
            <Box
                aria-label="Prompt"
                onKeyDownCapture={handlePromptKeyDownCapture}
                ref={handlePromptSurfaceRef}
                sx={{
                    borderRadius: '9px',
                    border: 1,
                    borderColor: 'custom.borderStrong',
                    display: 'flex',
                    flexDirection: 'column',
                    flexShrink: 0,
                    height: promptEmpty ? 'auto' : promptHeight,
                    overflow: 'hidden',
                    '&:focus-within': {
                        borderColor: 'primary.main',
                        boxShadow: (theme) => `0 0 0 3px ${theme.palette.action.selected}`,
                    },
                }}
            >
                <Box
                    data-testid="action-prompt-editor-region"
                    sx={{
                        flex: promptEmpty ? '0 0 auto' : 1,
                        height: promptEmpty ? EMPTY_PROMPT_EDITOR_HEIGHT : undefined,
                        mb: promptEmpty ? -1.5 : 1,
                        minHeight: 0,
                        overflowY: 'auto',
                        px: 1,
                    }}
                >
                    <MarkdownEditor
                        attachmentHandler={attachmentHandler}
                        flushOnBlur
                        hideToolbar
                        localTextSearch={false}
                        markdown={prompt}
                        onChange={handlePromptChange}
                        onLiveChange={handleLivePromptChange}
                        placeholders={ACTION_PROMPT_PLACEHOLDERS}
                        readOnly={disabled || editorSnapshot.preparationStatus !== 'ready'}
                        ref={promptEditorRef}
                    />
                </Box>
                {responsePrompts}
                {bottomRow}
            </Box>
            {convertMessage ? (
                <Typography color="text.secondary" role="status" variant="caption">
                    {convertMessage}
                </Typography>
            ) : null}
        </>
    )
}

import { useCallback, useEffect, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import type { ActionDefinition } from '../../../data/action_types'
import type { ActionRun } from '../../../services/actions/action_run_registry'
import type { ActionRunSettingsStore } from '../../../services/actions/action_run_settings_service'
import { dialogService } from '../../../services/dialog_service'
import { remoteConnectionService } from '../../../services/data/remote_connection_service'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import { ActionAgentPrompt } from './action_agent_prompt'
import type { ActionConversationStore } from '../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../run/state/action_history_store'
import { currentActionPromptDraft, runPopupAction } from '../run/popup/action_popup_operations'
import { actionPopupRunDisabled } from '../run/popup/action_popup_run_disabled'
import type { ActionRunInputStore } from '../run/state/action_run_input_store'
import type { ActionRunResultStore } from '../run/state/action_run_result_store'
import type { ActionScheduleStore } from '../run/schedule/action_schedule_store'
import { defaultPreparePrompt } from '../run/popup/action_popup_defaults'
import { ActionPopupBottomRow } from '../run/popup/action_popup_bottom_row'
import type { ActionUsageScopeStore } from '../run/popup/action_usage_scope_store'
import { useActionRunSettings } from '../shared/use_action_run_settings'
import { ActionPhraseButtonsOwner } from '../editor/action_phrase_buttons_owner'

interface ActionAgentPromptOwnerProps {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    scheduleStore: ActionScheduleStore
    settingsStore: ActionRunSettingsStore
    usageScopeStore: ActionUsageScopeStore
}

function selectSessionActive(run: ActionRun | null) {
    return run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
}

/** Owns prompt draft binding, preparation, and keyboard-run behavior. */
export function ActionAgentPromptOwner(props: ActionAgentPromptOwnerProps) {
    const {
        action, context, conversationStore, historyStore, inputStore, resultStore, runValidationError,
        scheduleStore, settingsStore, usageScopeStore,
    } = props
    const sessionActive = useActionRunSelector(action.id, context, selectSessionActive)
    const activeActionType = useActionRunSelector(action.id, context, (run) => run?.activeActionType ?? null)
    const hasApprovals = useActionRunSelector(action.id, context, (run) => !!run?.approvals.length)
    const hasQuestion = useActionRunSelector(action.id, context, (run) => !!run?.question)
    const interactionReady = useActionRunSelector(action.id, context, (run) => !!run?.interactionReady)
    const runStatus = useActionRunSelector(action.id, context, (run) => run?.status ?? 'idle')
    const conversationSnapshot = useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const inputSnapshot = useSyncExternalStore(inputStore.subscribe, inputStore.getSnapshot, inputStore.getSnapshot)
    const remoteConnection = useSyncExternalStore(
        remoteConnectionService.subscribe,
        remoteConnectionService.getSnapshot,
        remoteConnectionService.getSnapshot,
    )
    const settings = useActionRunSettings(action, settingsStore)
    const prepare = action.type === 'agent'
        && !sessionActive
        && runStatus !== 'completed'
        && conversationSnapshot.selectedConversation === null
    const promptDraft = currentActionPromptDraft(action, context, prepare)
    const handleAttachments = useCallback(async (files: File[], insertMarkdown: (markdown: string) => void) => {
        if ((context.kind !== 'card' && context.kind !== 'file') || !context.file) {
            throw new Error('Card action prompt attachments require a selected card')
        }

        const { attachFilesToCardMarkdown } = await import('../../../services/attachments/attachment_workflow')
        await attachFilesToCardMarkdown(context.file, files, insertMarkdown)
    }, [context])
    const attachmentHandler = (context.kind === 'card' || context.kind === 'file') && context.file
        ? handleAttachments
        : undefined

    useEffect(() => {
        if (!prepare || remoteConnection.status === 'connecting' || remoteConnection.status === 'reconnecting') return

        void promptDraft.prepare(() => defaultPreparePrompt(action, context)).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Could not prepare action prompt' })
        })
    }, [action, context, prepare, promptDraft, remoteConnection.status])

    const handleRunShortcut = () => {
        const prompt = promptDraft.getSnapshot()
        const runState = {
            agentActive: sessionActive && activeActionType === 'agent',
            hasApprovals,
            hasQuestion,
            interactionReady,
            runDisabledMessage: settings.runDisabledMessage,
            runStatus,
        }
        if (actionPopupRunDisabled(
            action,
            runState,
            prompt,
            promptDraft.getEditorSnapshot().preparationStatus,
        )) return

        const operationInput = {
            action,
            context,
            conversationStore,
            historyStore,
            inputStore,
            resultStore,
            runValidationError,
            settings,
            settingsStore,
        }
        void runPopupAction(operationInput)
    }

    return (
        <ActionAgentPrompt
            attachmentHandler={attachmentHandler}
            bottomRow={action.type === 'agent' || activeActionType === 'agent' ? (
                <ActionPopupBottomRow
                    action={action}
                    assignmentContext={context}
                    conversationStore={conversationStore}
                    embedded
                    historyStore={historyStore}
                    inputStore={inputStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                    settingsStore={settingsStore}
                    usageScopeStore={usageScopeStore}
                />
            ) : undefined}
            convertMessage={inputSnapshot.convertMessage}
            disabled={false}
            onRunShortcut={handleRunShortcut}
            promptDraft={promptDraft}
            responsePrompts={(
                <ActionPhraseButtonsOwner
                    action={action}
                    context={context}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    settingsStore={settingsStore}
                />
            )}
        />
    )
}

