        renderBottomRow(action, conversationStore)

        const finish = screen.getByRole('button', { name: 'Finish' })
        fireEvent.mouseOver(finish)
        expect(await screen.findByText(/Ctrl\+click or long press to stop sequence/u, { selector: '.MuiTooltip-tooltip' }))
            .toBeInTheDocument()
        fireEvent.click(finish, { ctrlKey: true })

        expect(screen.getByRole('dialog', { name: 'Stop action sequence?' })).toBeInTheDocument()
        expect(closeWaitingActionConversation).not.toHaveBeenCalled()
        fireEvent.click(screen.getByRole('button', { name: outcome }))
        await vi.waitFor(() => expect(closeWaitingActionConversation).toHaveBeenCalledWith(source.path, status))
    })

    it('opens confirmation after long press and suppresses release click', async () => {
        const source = waitingConversation(action.id)
        const closeWaitingActionConversation = vi.fn()
        window.md2Actions = {
            closeWaitingActionConversation,
            onActionRun: vi.fn(() => vi.fn()),
        } as unknown as typeof window.md2Actions
        vi.spyOn(dataService, 'listAgentConversations').mockResolvedValue([source])
        const conversationStore = new ActionConversationStore(action.id, context)
        await conversationStore.load()
        renderBottomRow(action, conversationStore)
        vi.useFakeTimers()
        const finish = screen.getByRole('button', { name: 'Finish' })

        fireEvent.pointerDown(finish, { button: 0, pointerId: 7 })
        act(() => vi.advanceTimersByTime(500))
        expect(screen.getByRole('dialog', { name: 'Stop action sequence?' })).toBeInTheDocument()
        fireEvent.pointerUp(finish, { pointerId: 7 })
        fireEvent.click(finish)

        expect(closeWaitingActionConversation).not.toHaveBeenCalled()
    })

    it('performs no operation when long press is cancelled before 500 ms', async () => {
        const source = waitingConversation(action.id)
        const closeWaitingActionConversation = vi.fn()
        window.md2Actions = {
            closeWaitingActionConversation,
            onActionRun: vi.fn(() => vi.fn()),
        } as unknown as typeof window.md2Actions
        vi.spyOn(dataService, 'listAgentConversations').mockResolvedValue([source])
        const conversationStore = new ActionConversationStore(action.id, context)
        await conversationStore.load()
        renderBottomRow(action, conversationStore)
        vi.useFakeTimers()
        const finish = screen.getByRole('button', { name: 'Finish' })

        fireEvent.pointerDown(finish, { button: 0, pointerId: 8 })
        act(() => vi.advanceTimersByTime(499))
        fireEvent.pointerCancel(finish, { pointerId: 8 })
        act(() => vi.advanceTimersByTime(1))

        expect(screen.queryByRole('dialog', { name: 'Stop action sequence?' })).not.toBeInTheDocument()
        expect(closeWaitingActionConversation).not.toHaveBeenCalled()
    })

    it('reports stale persisted waiting state and keeps orphan controls', async () => {
        const source = waitingConversation(action.id)
        const staleError = new Error('Agent conversation is no longer waiting for input')
        window.md2Actions = {
            closeWaitingActionConversation: vi.fn(async () => { throw staleError }),
            onActionRun: vi.fn(() => vi.fn()),
        } as unknown as typeof window.md2Actions
        const reportError = vi.spyOn(dialogService, 'error').mockReturnValue({
            critical: false,
            id: 1,
            message: staleError.message,
            severity: 'error',
            title: 'Error',
        })
        vi.spyOn(dataService, 'listAgentConversations').mockResolvedValue([source])
        const conversationStore = new ActionConversationStore(action.id, context)
        await conversationStore.load()
        actionPromptDraftService.getDraft(action.id, context, null, { prepare: false }).edit('Continue')
        renderBottomRow(action, conversationStore)

        fireEvent.click(screen.getByRole('button', { name: 'Finish' }))

        await vi.waitFor(() => expect(reportError).toHaveBeenCalledWith(staleError, {fallbackMessage: 'Could not finish waiting agent conversation'}))
        expect(screen.getByRole('button', { name: 'Finish' })).toBeEnabled()
        expect(screen.queryByRole('button', { name: 'Stop' })).not.toBeInTheDocument()
    })
})

import { ACTION_APPLIES_TO_FIELDS, CUSTOM_PROMPT_ACTION_ID } from './action_types'
import type { ActionAppliesToField, ActionDefinition } from './action_types'
import type { Card, CardHeader, CardTypeConfig } from './data_types'
import { getCardIdPrefix } from './card_identifiers'

/** The kind of item an action entry point is attached to. */
export type ActionContextKind = 'card' | 'file' | 'folder' | 'merge-conflict' | 'project'

export type ActionContextFilterValueSource =
    'kind' | 'type' | 'state' | 'file' | 'folder' | 'worktree' | 'text'

export interface ActionContextFilterDescriptor {
    key: ActionAppliesToField
    label: string
    supportedContextKinds: ActionContextKind[]
    valueSource: ActionContextFilterValueSource
    validate: (value: string) => string | null
}

/**
 * The selected item an action is evaluated against. `appliesTo` keys are matched
 * field-by-field against this object, so every matchable property is a string.
 */
export interface ActionContext {
    /** Stable card identity used for activity ownership. */
    cardInternalId?: string
    /** Title of the selected card, used for placeholder resolution. */
    title?: string
    /** Card/file type derived from the id prefix, e.g. `feature`. */
    type?: string
    /** Card state / status, e.g. `design`. */
    state?: string
    /** Path to the markdown file, used for placeholder resolution. */
    file?: string
    /** Folder name for folder contexts. */
    folder?: string
    /** Selected conflicted repository-relative path. */
    conflictFile?: string
    /** Newline-separated conflicted repository-relative paths. */
    conflictFiles?: string
    /** Active desktop conflict session binding. */
    conflictSessionId?: string
    kind: ActionContextKind
    worktree?: string
    worktreeError?: string
    [key: string]: string | undefined
}

/**
 * Stable identity of the item an action runs against, used to match a popup to its
 * execution and conversation history. Mutable header fields (title, state, worktree)
 * are excluded on purpose: a run that edits its own card must keep the same identity.
 */
export function actionContextIdentity(context: ActionContext): string {
    if (context.kind === 'project') return 'project'
    if (context.kind === 'folder') return `folder�${context.folder ?? ''}`
    if (context.kind === 'merge-conflict') {
        return `merge-conflict�${context.conflictSessionId ?? ''}�${context.conflictFile ?? ''}`
    }

    return `${context.kind}�${context.cardInternalId ?? context.file ?? ''}`
}

/** Required-value validation shared by every applicability filter descriptor. */
export function validateActionContextFilterValue(value: string): string | null {
    return value.length > 0 ? null : 'Required value'
}

const ACTION_CONTEXT_FILTER_METADATA: Record<ActionAppliesToField, Omit<ActionContextFilterDescriptor, 'key'>> = {
    file: { label: 'Repository file', supportedContextKinds: ['card', 'file'], valueSource: 'file', validate: validateActionContextFilterValue },
    folder: { label: 'Repository folder', supportedContextKinds: ['folder'], valueSource: 'folder', validate: validateActionContextFilterValue },
    kind: { label: 'Target kind', supportedContextKinds: ['card', 'file', 'folder', 'merge-conflict', 'project'], valueSource: 'kind', validate: validateActionContextFilterValue },
    state: { label: 'Card state', supportedContextKinds: ['card', 'file'], valueSource: 'state', validate: validateActionContextFilterValue },
    type: { label: 'Context type', supportedContextKinds: ['card', 'file', 'folder'], valueSource: 'type', validate: validateActionContextFilterValue },
    worktree: { label: 'Worktree', supportedContextKinds: ['card', 'file', 'project'], valueSource: 'worktree', validate: validateActionContextFilterValue },
    worktreeError: { label: 'Worktree error', supportedContextKinds: ['card', 'file'], valueSource: 'text', validate: validateActionContextFilterValue },
}

export const ACTION_CONTEXT_FILTER_DESCRIPTORS: ActionContextFilterDescriptor[] = ACTION_APPLIES_TO_FIELDS.map((key) => ({
    key,
    ...ACTION_CONTEXT_FILTER_METADATA[key],
}))

/** Resolve the configured card type for a card id via its prefix (e.g. `F-005` â†’ `feature`). */
export function getCardType(cardTypes: CardTypeConfig[], id: string): string | undefined {
    const prefix = getCardIdPrefix(id)

    return cardTypes.find((cardType) => cardType.idPrefix === prefix)?.type
}

type MarkdownContextCard = Pick<Card, 'path'> & {
    header: Pick<CardHeader, 'id' | 'internalId' | 'status' | 'title' | 'worktreeError' | 'worktreeValue'>
}

function markdownContext(card: MarkdownContextCard, cardTypes: CardTypeConfig[], kind: ActionContextKind): ActionContext {
    const context: ActionContext = { file: card.path, kind, title: card.header.title }
    const type = getCardType(cardTypes, card.header.id)
    if (card.header.internalId) context.cardInternalId = card.header.internalId
    if (type) context.type = type
    if (card.header.status) context.state = card.header.status
    if (card.header.worktreeValue) context.worktree = card.header.worktreeValue
    if (card.header.worktreeError) context.worktreeError = card.header.worktreeError

    return context
}

/** Build the action context for a card shown in card view. */
export function cardContext(card: MarkdownContextCard, cardTypes: CardTypeConfig[]): ActionContext {
    if (!card.header.internalId) throw new Error(`Cannot build action context without an internal ID: ${card.path}`)

    return markdownContext(card, cardTypes, 'card')
}

/**
 * Build the action context for a markdown file in the tree/text view. Regular markdown files
 * are not cards and carry no internal ID, so the context stays without card identity.
 */
export function fileContext(card: Card, cardTypes: CardTypeConfig[]): ActionContext {
    return markdownContext(card, cardTypes, 'file')
}

/** Build the action context for a folder node in the tree. */
export function folderContext(folder: string, isSpecial = false): ActionContext {
    const context: ActionContext = { folder, kind: 'folder' }
    if (isSpecial) context.type = folder

    return context
}

/** Build context for actions that run against the opened project rather than a card or file. */
export function projectContext(): ActionContext {
    return { kind: 'project' }
}

/** Add or remove the session assignment used by project-wide popup actions. */
export function projectContextWithWorktree(context: ActionContext, worktree: number | null): ActionContext {
    if (context.kind !== 'project') return context
    if (worktree === null) {
        const unassignedContext = { ...context }
        delete unassignedContext.worktree

        return unassignedContext
    }

    return { ...context, worktree: String(worktree) }
}

/**
 * True when the action is allowed in the given context. An action with no
 * `appliesTo` (like the built-in custom prompt) matches every context; otherwise
 * every `appliesTo` key must equal the same field on the context.
 */
export function actionMatchesContext(action: ActionDefinition, context: ActionContext): boolean {
    if (!action.appliesTo) return true

    return ACTION_APPLIES_TO_FIELDS.every((key) => action.appliesTo?.[key] === undefined || context[key] === action.appliesTo[key])
}

/** All actions that should be shown for a context, preserving load order. */
export function actionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    return actions.filter((action) => (!action.builtin || action.id === CUSTOM_PROMPT_ACTION_ID) && actionMatchesContext(action, context))
}

/** Context actions in selector order, with the built-in custom prompt last. */
export function displayActionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    const contextActions = actionsForContext(actions, context)
    const customPrompt = contextActions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID)
    const configuredActions = contextActions.filter(({ id }) => id !== CUSTOM_PROMPT_ACTION_ID)

    return customPrompt ? [...configuredActions, customPrompt] : configuredActions
}

